type IconProperties = {
  name: IconName;
  size?: number;
  className: string;
};

export const Icon = ({ name, size = 24, className }: IconProperties) => {
  const iconData = IconPathRegistry[name];

  return (
    <svg
      width={size}
      height={size}
      viewBox={iconData.viewBox ?? '0 0 24 24'}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
    >
      {iconData.path}
    </svg>
  );
};

export function isIconName(key: string): key is keyof typeof IconPathRegistry {
  return key in IconPathRegistry;
}
